try:
    DAILY_ZONE = ZoneInfo('America/New_York')
except Exception:
    DAILY_ZONE = None  # run_job publishes a clear error archive via self checks
NEW_FAMILIES = ('SIGNAL_CLOSE_MAX','PREVIOUS_CLOSE_MIN','D1_ABOVE_EMA','D1_BELOW_EMA','D1_VOL_MIN','D1_VOL_MAX')
AVAILABILITY_IDS = tuple(b+'_AVAILABLE_D1_EMA_W'+str(n) for b in ANCHORS for n in (100,200)) + tuple(b+'_AVAILABLE_D1_VOL_W050' for b in ANCHORS)
COMPARISON_IDS = PARENT_IDS + AVAILABILITY_IDS
FAMILIES = {}
for _branch in ANCHORS:
    for _kind,_levels in (('SIGNAL_CLOSE_MAX',(.25,.35,.45)),('PREVIOUS_CLOSE_MIN',(.50,.65,.80)),('D1_VOL_MIN',(.75,1.,1.25)),('D1_VOL_MAX',(.75,1.,1.25))):
        FAMILIES[_branch+'_'+_kind] = dict(axes={'threshold':_levels})
    for _kind in ('D1_ABOVE_EMA','D1_BELOW_EMA'):
        FAMILIES[_branch+'_'+_kind] = dict(axes={'feature_window':(100,200)})

def timezone_identity():
    identities=[]
    for directory in TZPATH:
        folder=Path(directory)
        zone=folder/'America/New_York'
        if zone.is_file():
            version=folder/'tzdata.zi'
            header=version.open().readline().strip() if version.is_file() else None
            identities.append(dict(zone_file_sha256=file_sha(zone),version_header=header))
            break
    if not identities:
        # ZoneInfo may resolve the standard tzdata wheel rather than system paths.
        try:
            import importlib.metadata
            identities.append(dict(tzdata_package_version=importlib.metadata.version('tzdata')))
        except importlib.metadata.PackageNotFoundError:
            raise RuntimeError('Cannot identify installed New York timezone database')
    return identities

def daily_bounds(t):
    """Half-open NY 17:00 session containing a native candle OPEN timestamp."""
    if DAILY_ZONE is None:
        raise RuntimeError('New York IANA timezone data unavailable; install system tzdata before running this research')
    local = t.astimezone(DAILY_ZONE)
    day = local.date()
    if local.hour < 17:
        day -= timedelta(days=1)
    a = datetime.combine(day, datetime.min.time(), DAILY_ZONE).replace(hour=17)
    b = datetime.combine(day + timedelta(days=1), datetime.min.time(), DAILY_ZONE).replace(hour=17)
    return a.astimezone(UTC), b.astimezone(UTC)


def seeded_ema(closes, period):
    result = [None] * len(closes)
    if len(closes) >= period:
        value = math.fsum(closes[:period]) / period
        result[period-1] = value
        alpha = 2.0 / (period + 1)
        for j in range(period, len(closes)):
            value = alpha * closes[j] + (1.0-alpha) * value
            result[j] = value
    return result


def build_daily(bars, volumes=None):
    """Derived daily context; no native D1 quote request or fabricated empty day."""
    if not bars:
        return []
    cutoff = min(END, bars[-1][0] + BAR)
    groups = {}
    for i, (t, op, hi, lo, cl) in enumerate(bars):
        a, b = daily_bounds(t)
        if not a <= t < t + BAR <= b:
            raise RuntimeError('Native M15 candle crosses a declared daily boundary')
        if b not in groups:
            groups[b] = dict(period_start=iso(a), period_end=iso(b), open=op, high=hi, low=lo,
                close=cl, first_source_index=i, last_source_index=i, native_m15_count=0,
                summed_price_count=0 if volumes is not None else None,
                left_censored=int(a < bars[0][0]), right_censored=int(b > cutoff))
        row = groups[b]
        row['high'] = max(row['high'], hi)
        row['low'] = min(row['low'], lo)
        row['close'], row['last_source_index'] = cl, i
        row['native_m15_count'] += 1
        if volumes is not None:
            row['summed_price_count'] += volumes[t]
    rows = [groups[b] for b in sorted(groups)]
    complete = []
    for row in rows:
        row['complete'] = int(not row['left_censored'] and not row['right_censored'])
        row.update(daily_index=None, atr14=None, atr14_preceding50_mean=None,
                   atr14_ratio50=None, ema100=None, ema200=None)
        if row['complete']:
            row['daily_index'] = len(complete)
            complete.append(row)
    dbars = [(when(r['period_start']), r['open'], r['high'], r['low'], r['close']) for r in complete]
    atr = atr14(dbars)
    closes = [r['close'] for r in complete]
    emas = {n: seeded_ema(closes, n) for n in (100, 200)}
    for j, row in enumerate(complete):
        row.update(atr14=atr[j], ema100=emas[100][j], ema200=emas[200][j])
        if j >= 64:
            previous = atr[j-50:j]  # excludes numerator session
            if len(previous) == 50 and all(x is not None and x > 0 for x in previous):
                mean = math.fsum(previous) / 50
                row['atr14_preceding50_mean'] = mean
                row['atr14_ratio50'] = atr[j] / mean if atr[j] is not None and atr[j] > 0 else None
    return rows


def make_configs():
    archived, _ = make_archived_configs()
    configs = [dict(c) for c in archived]
    memberships = [dict(requested_label=c['config_id'], stage_group='ARCHIVED_PASS2B',
                        config_id=c['config_id']) for c in archived]
    by_id = {c['config_id']: c for c in configs}
    for branch, anchor_id in ANCHORS.items():
        memberships.append(dict(requested_label=branch+'_UNFILTERED',
            stage_group='ANCHOR_REFERENCE', config_id=anchor_id))
        anchor = by_id[anchor_id]
        def add(kind, window, threshold, role):
            suffix = f'_W{window:03d}' if window else ''
            if threshold is not None:
                suffix += f'_T{round(threshold*100):03d}'
            cid = branch+'_'+kind+suffix
            config = dict(anchor, config_id=cid, anchor_id=anchor_id,
                          feature_family=kind, feature_window=window, threshold=threshold)
            if cid in by_id:
                raise RuntimeError('Duplicate Pass2C definition')
            by_id[cid] = config
            configs.append(config)
            memberships.append(dict(requested_label=cid, stage_group=role, config_id=cid))
        for kind, levels in (('SIGNAL_CLOSE_MAX', (.25,.35,.45)),
                             ('PREVIOUS_CLOSE_MIN', (.50,.65,.80)),
                             ('D1_VOL_MIN', (.75,1.0,1.25)), ('D1_VOL_MAX', (.75,1.0,1.25))):
            for threshold in levels:
                add(kind, 50 if kind.startswith('D1_VOL') else 0, threshold, branch+'_'+kind)
        for kind in ('D1_ABOVE_EMA','D1_BELOW_EMA'):
            for window in (100,200):
                add(kind, window, None, branch+'_'+kind)
        for window in (100,200):
            add('AVAILABLE_D1_EMA',window,None,'AVAILABILITY_CONTROL')
        add('AVAILABLE_D1_VOL',50,None,'AVAILABILITY_CONTROL')
    assert len(configs) == 68 and len(memberships) == 70
    assert len({config_key(c) for c in configs}) == 68
    assert len([c for c in configs if is_research(c)]) == 32
    assert len([c for c in configs if is_availability(c)]) == 6
    assert set(c['config_id'] for c in configs if c['config_id'] in PARENT_IDS) == set(PARENT_IDS)
    return configs, memberships


def is_research(config):
    return config.get('feature_family') in NEW_FAMILIES


def is_availability(config):
    return config.get('feature_family') in ('AVAILABLE_D1_EMA','AVAILABLE_D1_VOL')


def comparison_control(config):
    kind = config.get('feature_family')
    if not is_research(config):
        return None
    branch = next(b for b,a in ANCHORS.items() if a == config['anchor_id'])
    if kind in ('D1_ABOVE_EMA','D1_BELOW_EMA'):
        return f'{branch}_AVAILABLE_D1_EMA_W{config["feature_window"]:03d}'
    if kind in ('D1_VOL_MIN','D1_VOL_MAX'):
        return branch+'_AVAILABLE_D1_VOL_W050'
    return config['anchor_id']


def make_features(bars):
    raw = make_legacy_features(bars)
    daily = [r for r in build_daily(bars) if r['complete']]
    ends = [when(r['period_end']) for r in daily]
    for i,row in raw.items():
        previous = bars[i-1]
        width = previous[2]-previous[3]
        row['previous_close_location'] = (previous[4]-previous[3])/width if width > 0 else None
        decision = bars[i][0]+BAR
        j = bisect.bisect_right(ends, decision)-1
        context = daily[j] if j >= 0 else None
        row.update(daily_index=j if context else None,
            daily_period_end=context['period_end'] if context else None,
            daily_context_age_hours=(decision-ends[j]).total_seconds()/3600 if context else None,
            daily_close=context['close'] if context else None,
            daily_atr14=context['atr14'] if context else None,
            daily_atr14_preceding50_mean=context['atr14_preceding50_mean'] if context else None,
            daily_atr14_ratio50=context['atr14_ratio50'] if context else None,
            daily_ema100=context['ema100'] if context else None,
            daily_ema200=context['ema200'] if context else None)
    return raw


def selected_indices(config, features):
    kind = config.get('feature_family')
    if kind is None or kind in ('MOMENTUM_UP','VOL_MIN','VOL_MAX'):
        return selected_legacy_indices(config, features)
    if kind not in NEW_FAMILIES and not is_availability(config):
        raise RuntimeError('Unsupported Pass2C condition: '+str(kind))
    indices = base_selected_indices(config, features)
    window, threshold = config['feature_window'], config['threshold']
    def qualifies(row):
        if kind in ('SIGNAL_CLOSE_MAX','PREVIOUS_CLOSE_MIN'):
            value = row['close_location' if kind == 'SIGNAL_CLOSE_MAX' else 'previous_close_location']
            return value is not None and (value <= threshold if kind == 'SIGNAL_CLOSE_MAX' else value >= threshold)
        if kind in ('D1_ABOVE_EMA','D1_BELOW_EMA','AVAILABLE_D1_EMA'):
            close, ema = row['daily_close'], row[f'daily_ema{window}']
            if close is None or ema is None:
                return False
            return kind == 'AVAILABLE_D1_EMA' or (close > ema if kind == 'D1_ABOVE_EMA' else close < ema)
        value = row['daily_atr14_ratio50']
        return value is not None and (kind == 'AVAILABLE_D1_VOL' or
            (value <= threshold if kind == 'D1_VOL_MAX' else value >= threshold))
    return [i for i in indices if qualifies(features[i])]


def load_frozen_history(work):
    bars,volumes,h1,hvolumes = load_archived18_history(work)
    payload = zlib.decompress(base64.b85decode(PASS2B_REFERENCE_B85.encode()))
    if sha(payload) != PASS2B_REFERENCE_SHA256:
        raise RuntimeError('Pass2B accepted reference checksum failed')
    data = json.loads(payload)
    if len(data['rows']) != PASS2B_REFERENCE_ROWS or len(data['summaries']) != 72:
        raise RuntimeError('Incomplete latest Pass2B reference')
    ledger = work/'parent_pass1_accepted_ledgers.csv'
    with ledger.open(newline='') as f:
        fields = next(csv.reader(f))
    with ledger.open('a',newline='') as f:
        writer = csv.DictWriter(f,fieldnames=fields)
        for row in data['rows']:
            writer.writerow(row)
    provenance = json.loads((work/'parent_pass1_provenance.json').read_text())
    provenance['parent_summaries'].extend(data['summaries'])
    provenance.update(pass2b_results_zip_sha256=PASS2B_ZIP_SHA256,
        pass2b_latest_reference_sha256=PASS2B_REFERENCE_SHA256, combined_parent_accepted_rows=122338)
    write_json(work/'parent_pass1_provenance.json',provenance)
    write_json(work/'pass2b_latest_reference.json',data)
    return bars,volumes,h1,hvolumes


def daily_feature_controls(bars,features):
    """Independent boundary-calendar grouping and indicator recurrences."""
    checks=[]
    def check(name,actual,expected=True):
        checks.append(dict(check=name,status='PASS' if actual==expected else 'FAIL',actual=actual,expected=expected))
    first = bars[0][0].astimezone(DAILY_ZONE).date()-timedelta(days=2)
    last = bars[-1][0].astimezone(DAILY_ZONE).date()+timedelta(days=2)
    boundaries=[]
    day=first
    while day <= last:
        boundaries.append(datetime(day.year,day.month,day.day,17,tzinfo=DAILY_ZONE).astimezone(UTC))
        day += timedelta(days=1)
    groups={}
    for i,bar in enumerate(bars):
        bucket=bisect.bisect_right(boundaries,bar[0])-1
        a,b=boundaries[bucket:bucket+2]
        groups.setdefault((a,b),[]).append(i)
    independent=[]
    cutoff=min(END,bars[-1][0]+BAR)
    for (a,b),ids in sorted(groups.items()):
        if a < bars[0][0] or b > cutoff:
            continue
        independent.append((a,b,bars[ids[0]][1],max(bars[i][2] for i in ids),
                            min(bars[i][3] for i in ids),bars[ids[-1]][4],ids))
    actual=[r for r in build_daily(bars) if r['complete']]
    check('derived_daily_count_matches_independent_boundary_calendar',len(actual),len(independent))
    matches = len(actual)==len(independent)
    for r,d in zip(actual,independent):
        matches &= (r['period_start'],r['period_end'],r['open'],r['high'],r['low'],r['close'],
                    r['native_m15_count'],r['first_source_index'],r['last_source_index']) == (
                    iso(d[0]),iso(d[1]),*d[2:6],len(d[6]),d[6][0],d[6][-1])
    check('all_derived_daily_OHLC_and_source_membership_match_independently',matches)
    tr=[None]+[max(d[3]-d[4],abs(d[3]-independent[j-1][5]),abs(d[4]-independent[j-1][5]))
               for j,d in enumerate(independent) if j]
    atr=[None]*len(independent)
    if len(atr)>14:
        atr[14]=sum(tr[1:15])/14
        for j in range(15,len(atr)):
            atr[j]=atr[j-1]+(tr[j]-atr[j-1])/14
    closes=[d[5] for d in independent]
    emas={}
    for n in (100,200):
        vals=[None]*len(closes)
        if len(closes)>=n:
            vals[n-1]=sum(closes[:n])/n
            for j in range(n,len(closes)):
                vals[j]=vals[j-1]+2/(n+1)*(closes[j]-vals[j-1])
        emas[n]=vals
    max_error=defaultdict(float)
    missing=defaultdict(int)
    ends=[d[1] for d in independent]
    future=0
    for i,row in features.items():
        decision=bars[i][0]+BAR
        j=bisect.bisect_right(ends,decision)-1
        if row['daily_period_end'] is not None:
            future += when(row['daily_period_end'])>decision
        po,ph,pl,pc=bars[i-1][1:]
        expected={'previous_close_location':(pc-pl)/(ph-pl) if ph>pl else None,
            'daily_close':closes[j] if j>=0 else None,
            'daily_atr14':atr[j] if j>=0 else None,
            'daily_ema100':emas[100][j] if j>=0 else None,
            'daily_ema200':emas[200][j] if j>=0 else None}
        mean=None
        if j>=64 and all(v is not None and v>0 for v in atr[j-50:j]):
            mean=sum(atr[j-50:j])/50
        expected['daily_atr14_preceding50_mean']=mean
        expected['daily_atr14_ratio50']=atr[j]/mean if mean is not None and atr[j] is not None and atr[j]>0 else None
        for key,want in expected.items():
            got=row[key]
            if (want is None)!=(got is None):
                missing[key]+=1
            elif want is not None:
                max_error[key]=max(max_error[key],abs(want-got))
    check('no_daily_context_completed_after_signal_decision',future,0)
    for key in ('previous_close_location','daily_close','daily_atr14','daily_ema100','daily_ema200',
                'daily_atr14_preceding50_mean','daily_atr14_ratio50'):
        check(key+'_independent_values_and_missingness',missing[key]==0 and max_error[key]<=1e-10)
    return checks


def conditional_feature_controls(bars,features):
    legacy=legacy_conditional_feature_controls(bars,features)
    rows=[dict(check=r['check'],status=r['status'],actual=json.dumps({
        'missing_mismatches':r['missing_value_mismatches'],'max_error':r['maximum_absolute_error']}),
        expected='missing=0; max_error<=1e-10') for r in legacy]
    return rows+daily_feature_controls(bars,features)


def export_own_anchor_comparisons(work,configs):
    anchors={c['config_id']:c.get('anchor_id') for c in configs if c.get('anchor_id')}
    available={c['config_id']:comparison_control(c) for c in configs if is_research(c)}
    for name, mapping in (('own_anchor_comparisons.csv',anchors),
                          ('matched_availability_comparisons.csv',available)):
        with (work/'accepted_comparisons.csv').open(newline='') as source:
            reader=csv.DictReader(source)
            write_csv(work/name,(r for r in reader if mapping.get(r['config_id'])==r['reference_config']),reader.fieldnames)


def export_extra_diagnostics(work,bars,features,paths,configs):
    """Descriptive buckets and genuine full-replay trade differences; no tuning."""
    parents={c['config_id']:c for c in configs}
    indices={cid:selected_indices(c,features) for cid,c in parents.items()}
    marginal=CSVFile(work/'conditional_marginal_entry_differences.csv',CASE+[
        'reference_config','change','signal_index','signal','entry','exit','reason','r',
        'qualifies_in_candidate','qualifies_in_reference','interpretation'])
    buckets=CSVFile(work/'stop_cost_attribution.csv',CASE+['bucket_axis','bucket',
        'accepted_entries','closed_trades','open_trades','total_r','winners','losers',
        'mean_r','interpretation'])
    group_rows=[]
    try:
        for model in MODELS:
            for cost in COSTS:
                accepted={cid:replay(ids,paths,model,cost)[0] for cid,ids in indices.items()}
                groups=defaultdict(list)
                for cid,ids in accepted.items():
                    digest=sha(json.dumps(ids,separators=(',',':')).encode())
                    groups[digest].append(cid)
                for digest,cids in sorted(groups.items()):
                    group_rows.append(dict(execution_model=model,cost_ticks=cost,
                        accepted_stream_sha256=digest,configuration_count=len(cids),
                        config_ids=';'.join(sorted(cids)),interpretation='Identical accepted signal indices at this model/cost; not independent evidence'))
                for config in configs:
                    cid=config['config_id']
                    if not (is_research(config) or is_availability(config) or cid in ANCHORS.values()):
                        continue
                    tag=dict(config_id=cid,execution_model=model,cost_ticks=cost)
                    if is_research(config) or is_availability(config):
                        refs={config['anchor_id']}
                        matched=comparison_control(config)
                        if matched:
                            refs.add(matched)
                        ours=set(accepted[cid])
                        ownraw=set(indices[cid])
                        for ref in sorted(refs):
                            theirs=set(accepted[ref]);refraw=set(indices[ref])
                            for change,difference in (('ADDED',ours-theirs),('REMOVED',theirs-ours)):
                                for i in sorted(difference):
                                    p=paths[i][model]
                                    marginal.add(dict(tag,reference_config=ref,change=change,signal_index=i,
                                        signal=p['signal'],entry=p['entry'],exit=p['exit'],reason=p['reason'],r=r_value(p,cost),
                                        qualifies_in_candidate=int(i in ownraw),qualifies_in_reference=int(i in refraw),
                                        interpretation='Full replay difference; added entry can replace an occupied/reference entry; removed entry can reflect filtering or occupancy'))
                    collected=defaultdict(list)
                    axes={'stop_pips':(5.,10.,20.,40.),'cost_fraction_reference_risk':(.05,.10,.20,.40)}
                    for axis,edges in axes.items():
                        for k in range(5):
                            collected[(axis,k)]=[]
                        for i in accepted[cid]:
                            p=paths[i][model]
                            risk=p['stop']-p['reference_entry']
                            value=risk/PIP if axis=='stop_pips' else cost*TICK/risk
                            collected[(axis,bisect.bisect_left(edges,value))].append(i)
                        for k in range(5):
                            ids=collected[(axis,k)]
                            rs=[r_value(paths[i][model],cost) for i in ids]
                            closed=[r for r in rs if r is not None]
                            label=(f'<= {edges[0]}' if k==0 else
                                   f'> {edges[-1]}' if k==4 else f'({edges[k-1]}, {edges[k]}]')
                            buckets.add(dict(tag,bucket_axis=axis,bucket=label,accepted_entries=len(ids),
                                closed_trades=len(closed),open_trades=len(rs)-len(closed),total_r=math.fsum(closed),
                                winners=sum(r>0 for r in closed),losers=sum(r<0 for r in closed),
                                mean_r=math.fsum(closed)/len(closed) if closed else None,
                                interpretation='Fixed descriptive attribution of accepted ledger, not a stop filter or independent counterfactual'))
    finally:
        marginal.close();buckets.close()
    write_csv(work/'distinct_accepted_signal_groups.csv',group_rows)
    return {'conditional_marginal_entry_differences.csv':marginal.count,'stop_cost_attribution.csv':buckets.count,
            'distinct_accepted_signal_groups.csv':len(group_rows)}


def pass2c_self_checks():
    checks=[]
    def check(value,name):
        if not value:
            raise AssertionError(name)
        checks.append(dict(check=name,status='PASS',evidence='SYNTHETIC_SOFTWARE_ONLY'))
    winter=daily_bounds(datetime(2020,1,2,21,45,tzinfo=UTC))
    summer=daily_bounds(datetime(2020,7,2,20,45,tzinfo=UTC))
    check(winter[1].hour==22 and summer[1].hour==21,'NY17 daily boundary observes winter/summer UTC offset')
    for day,hours in ((datetime(2020,3,8,12,tzinfo=UTC),23),(datetime(2020,11,1,12,tzinfo=UTC),25)):
        a,b=daily_bounds(day)
        check((b-a).total_seconds()/3600==hours,'Daily DST duration '+str(hours))
        check(daily_bounds(b)[0]==b,'Daily exact-boundary candle belongs to following session '+str(hours))
    closes=[float(i) for i in range(205)]
    e=seeded_ema(closes,100)
    check(all(x is None for x in e[:99]) and e[99]==49.5,'EMA has full-period SMA seed and missing warmup')
    config=next(c for c in make_configs()[0] if c['config_id']=='MAIN_SIGNAL_CLOSE_MAX_T035')
    f={0:dict(body_atr=2.,range_atr=2.,abs_distance_atr_200=.05,close_location=.35),
       1:dict(body_atr=2.,range_atr=2.,abs_distance_atr_200=.05,close_location=.3500001)}
    check(selected_indices(config,f)==[0],'Signal-close maximum includes exact equality')
    config=next(c for c in make_configs()[0] if c['config_id']=='MAIN_PREVIOUS_CLOSE_MIN_T065')
    for i,value in enumerate((.65,.6499999)):
        f[i]['previous_close_location']=value
    check(selected_indices(config,f)==[0],'Previous-close minimum includes exact equality')
    config=next(c for c in make_configs()[0] if c['config_id']=='MAIN_D1_ABOVE_EMA_W100')
    for i,value in enumerate((1.,None)):
        f[i].update(daily_close=1.,daily_ema100=value)
    check(selected_indices(config,f)==[],'Daily trend equality and missing indicator are not directional signals')
    config=next(c for c in make_configs()[0] if c['config_id']=='MAIN_AVAILABLE_D1_EMA_W100')
    check(selected_indices(config,f)==[0],'Availability reference includes trend equality without filtering')
    try:
        selected_indices(dict(config,feature_family='UNKNOWN'),f)
        check(False,'Unsupported feature fails closed')
    except RuntimeError:
        check(True,'Unsupported feature fails closed')
    check(sum(is_research(c) for c in make_configs()[0])==32,'Only 32 research definitions; no combined conditions')
    check(sum(is_availability(c) for c in make_configs()[0])==6,'Six separately labelled availability controls')
    t=datetime(2020,7,1,20,45,tzinfo=UTC)
    tiny=[(t,.9,1.1,.8,1.),(t+BAR,1.,1.2,.9,1.1),(t+2*BAR,1.1,1.3,1.,1.2)]
    d=build_daily(tiny)
    check(all(not r['complete'] for r in d),'Left-censored and still-forming daily groups excluded')
    # 220 full synthetic priced sessions with explicit daily boundary starts.
    bars=[]
    start=datetime(2019,1,1,17,tzinfo=DAILY_ZONE)
    for k in range(220):
        local=start+timedelta(days=k)
        t=local.astimezone(UTC)
        price=1.+k*.00001
        bars.append((t,price,price+.001,price-.001,price+.0002))
    # Append a candle at the next boundary to make preceding session complete.
    t=(start+timedelta(days=220)).astimezone(UTC)
    bars.append((t,1.,1.001,.999,1.))
    d=build_daily(bars)
    full=[r for r in d if r['complete']]
    check(len(full)==220 and full[64]['atr14_ratio50'] is not None,'Daily ATR ratio requires 50 preceding seeded values')
    check(full[63]['atr14_ratio50'] is None,'Daily ATR ratio missing before full baseline')
    modified=list(bars);modified[65]=(modified[65][0],1.,1.4,.6,1.)
    changed=[r for r in build_daily(modified) if r['complete']]
    check(changed[65]['atr14_preceding50_mean']==full[65]['atr14_preceding50_mean'],
          'Daily ATR denominator excludes numerator session')
    check(changed[65]['atr14_ratio50']!=full[65]['atr14_ratio50'],'Daily ATR numerator can change without denominator leakage')
    prefix=build_daily(bars[:101])
    check([r for r in prefix if r['complete']]==d[:100],'Future sessions do not change any completed daily prefix')
    return checks

